    fun body(kind:WeatherBuddyArt.Kind,day:Boolean)=when(kind) {
        WeatherBuddyArt.Kind.SUN->body_sun[if(day)0 else 1]
        WeatherBuddyArt.Kind.MOON->body_moon[if(day)0 else 1]
        WeatherBuddyArt.Kind.CLOUD->body_cloud[if(day)0 else 1]
        WeatherBuddyArt.Kind.RAIN->body_rain[if(day)0 else 1]
        WeatherBuddyArt.Kind.SNOW->body_snow[if(day)0 else 1]
        WeatherBuddyArt.Kind.STORM->body_storm[if(day)0 else 1]
        WeatherBuddyArt.Kind.MIST->body_mist[if(day)0 else 1]
        WeatherBuddyArt.Kind.UNKNOWN->body_unknown[if(day)0 else 1]
    }
    fun still(kind:WeatherBuddyArt.Kind,day:Boolean)=when(kind) {
        WeatherBuddyArt.Kind.SUN->still_sun[if(day)0 else 1]
        WeatherBuddyArt.Kind.MOON->still_moon[if(day)0 else 1]
        WeatherBuddyArt.Kind.CLOUD->still_cloud[if(day)0 else 1]
        WeatherBuddyArt.Kind.RAIN->still_rain[if(day)0 else 1]
        WeatherBuddyArt.Kind.SNOW->still_snow[if(day)0 else 1]
        WeatherBuddyArt.Kind.STORM->still_storm[if(day)0 else 1]
        WeatherBuddyArt.Kind.MIST->still_mist[if(day)0 else 1]
        WeatherBuddyArt.Kind.UNKNOWN->still_unknown[if(day)0 else 1]
    }
    fun effects(kind:WeatherBuddyArt.Kind)=when(kind) {
        WeatherBuddyArt.Kind.SUN->fx_sun
        WeatherBuddyArt.Kind.MOON->fx_moon
        WeatherBuddyArt.Kind.CLOUD->fx_cloud
        WeatherBuddyArt.Kind.RAIN->fx_rain
        WeatherBuddyArt.Kind.SNOW->fx_snow
        WeatherBuddyArt.Kind.STORM->fx_storm
        WeatherBuddyArt.Kind.MIST->fx_mist
        WeatherBuddyArt.Kind.UNKNOWN->fx_unknown
    }
    fun ground(kind:WeatherBuddyArt.Kind)=when(kind) {
        WeatherBuddyArt.Kind.RAIN->ground_rain
        WeatherBuddyArt.Kind.STORM->ground_storm
        WeatherBuddyArt.Kind.SNOW->ground_snow
        else->intArrayOf()
    }
    fun eyes(kind:WeatherBuddyArt.Kind,variant:Int):IntArray {
        val v=Math.floorMod(variant,6)
        return when(kind) {
            WeatherBuddyArt.Kind.SUN->arrayOf(eye_sun_0,eye_sun_1,eye_sun_2,eye_sun_3,eye_sun_4,eye_sun_5)[v]
            WeatherBuddyArt.Kind.MOON->arrayOf(eye_moon_0,eye_moon_1,eye_moon_2,eye_moon_3,eye_moon_4,eye_moon_5)[v]
            else->arrayOf(eye_cloud_0,eye_cloud_1,eye_cloud_2,eye_cloud_3,eye_cloud_4,eye_cloud_5)[v]
        }
    }
